    vals = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    # Only these pairs are valid for subtractive notation
    subtractives = {("I", "V"), ("I", "X"), ("X", "L"), ("X", "C"), ("C", "D"), ("C", "M")}
    if not s:
        raise ValueError("empty string")
    total = 0
    i = 0
    while i < len(s):
        ch = s[i]
        if ch not in vals:
            raise ValueError("invalid character")
        # Check for a valid subtractive pair
        if i + 1 < len(s) and vals[ch] < vals[s[i + 1]]:
            pair = (ch, s[i + 1])
            if pair not in subtractives:
                raise ValueError("invalid subtractive notation")
            total += vals[s[i + 1]] - vals[ch]
            i += 2
        else:
            total += vals[ch]
            i += 1
    return total

